CREATE FUNCTION techerp_api.notification_source_snapshot(p_entity text,p_record uuid,p_workspace uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
SELECT CASE p_entity
 WHEN 'leads' THEN (SELECT to_jsonb(r) FROM public.leads r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'contacts' THEN (SELECT to_jsonb(r) FROM public.contacts r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'companies' THEN (SELECT to_jsonb(r) FROM public.companies r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'deals' THEN (SELECT to_jsonb(r) FROM public.deals r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'tickets' THEN (SELECT to_jsonb(r) FROM public.tickets r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'activities' THEN (SELECT to_jsonb(r) FROM public.activities r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'ats_jobs' THEN (SELECT to_jsonb(r) FROM public.ats_jobs r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'ats_candidates' THEN (SELECT to_jsonb(r) FROM public.ats_candidates r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'ats_applications' THEN (SELECT to_jsonb(r) FROM public.ats_applications r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'ats_interviews' THEN (SELECT to_jsonb(r) FROM public.ats_interviews r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'ats_offers' THEN (SELECT to_jsonb(r) FROM public.ats_offers r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'people' THEN (SELECT to_jsonb(r) FROM public.people r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'people_documents' THEN (SELECT to_jsonb(r) FROM public.people_documents r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'hiring_preparation_requests' THEN (SELECT to_jsonb(r) FROM public.hiring_preparation_requests r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'hiring_fiscal_documents' THEN (SELECT to_jsonb(r) FROM public.hiring_fiscal_documents r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'projects' THEN (SELECT to_jsonb(r) FROM public.projects r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'project_tasks' THEN (SELECT to_jsonb(r) FROM public.project_tasks r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'project_milestones' THEN (SELECT to_jsonb(r) FROM public.project_milestones r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'contracts' THEN (SELECT to_jsonb(r) FROM public.contracts r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'financial_entries' THEN (SELECT to_jsonb(r) FROM public.financial_entries r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'bank_payments' THEN (SELECT to_jsonb(r) FROM public.bank_payments r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'quotes' THEN (SELECT to_jsonb(r) FROM public.quotes r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'proposals' THEN (SELECT to_jsonb(r) FROM public.proposals r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'services' THEN (SELECT to_jsonb(r) FROM public.services r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'recurring_plans' THEN (SELECT to_jsonb(r) FROM public.recurring_plans r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'subscription_invoices' THEN (SELECT to_jsonb(r) FROM public.subscription_invoices r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'customer_invoices' THEN (SELECT to_jsonb(r) FROM public.customer_invoices r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'whatsapp_messages' THEN (SELECT to_jsonb(r) FROM public.whatsapp_messages r WHERE id=p_record AND workspace_id=p_workspace)
 WHEN 'inbox_channel_occurrences' THEN (SELECT to_jsonb(r) FROM public.inbox_channel_occurrences r WHERE id=p_record AND workspace_id=p_workspace)
 ELSE NULL END
$$;
REVOKE ALL ON FUNCTION techerp_api.notification_source_snapshot(text,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
